files.content:
@font-face {
  font-family: Roboto-Flex-Variable;
  src:
    local('Roboto-Flex-Variable'),
    url(./fonts/Roboto-Flex-Variable.woff2)
    format('woff2 supports variations'),
    url(./fonts/Roboto-Flex-Variable.woff2) format('woff2-variations');
  font-display: swap;
}

@font-face {
  font-family: Roboto-Serif-Variable;
  src:
    local('Roboto-Serif-Variable'),
    url(./fonts/Roboto-Serif-Variable.woff2)
    format('woff2 supports variations'),
    url(./fonts/Roboto-Serif-Variable.woff2) format('woff2-variations');
  font-display: swap;
}

@font-face {
  font-family: Roboto-Serif-Italic-Variable;
  src:
    local('Roboto-Serif-Italic-Variable'),
    url(./fonts/Roboto-Serif-Italic-Variable.woff2)
    format('woff2 supports variations'),
    url(./fonts/Roboto-Serif-Italic-Variable.woff2)
    format('woff2-variations');
  font-display: swap;
}

body {
  --main-color: #fff;
  --accent-color: #152028;

  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  margin: 0;
  padding: 25px;
  color: var(--accent-color);
  font-family: Roboto-Flex-Variable, sans-serif;
  font-size: 18px;
  line-height: 25px;
  background-color: var(--main-color);
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
  min-block-size: 100vh;
}

@media (min-width: 536px) {
  body {
    padding: 50px;
  }
}

@media (prefers-color-scheme: dark) {
  body {
    --main-color: #152028;
    --accent-color: #fff;
  }
}

@media (prefers-color-scheme: light) {
  body {
    --main-color: #fff;
    --accent-color: #152028;
  }

  .quote {
    font-variation-settings: 'GRAD' 75;
  }
}

body:has(.theme-toggler__control_type_dark:checked) {
  --main-color: #152028;
  --accent-color: #fff;
}

body:has(.theme-toggler__control_type_light:checked) {
  --main-color: #fff;
  --accent-color: #152028;
}

body:has(.theme-toggler__control_type_light:checked) .quote {
  font-variation-settings: 'GRAD' 75;
}

.content {
  display: flex;
  flex-direction: column;
  flex-grow: 1;
  align-items: center;
}

.hero {
  display: flex;
  flex-direction: column;
  flex-grow: 1;
  justify-content: center;
  align-items: center;
  padding-block-start: 50px;
  padding-block-end: 50px;
  max-inline-size: 1200px;
  inline-size: 100%;
}

@media (min-width: 768px) {
  .hero {
    position: relative;
    flex-direction: row-reverse;
    justify-content: flex-end;
  }
}

.quote {
  display: flex;
  flex-direction: column;
  gap: 15px;
  padding: 25px;
  color: var(--main-color);
  font-family: Roboto-Serif-Variable, sans-serif;
  background-color: var(--accent-color);
}

@media (min-width: 768px) {
  .quote {
    box-sizing: border-box;
    inline-size: 60%;
  }
}

.quote__content,
.quote__text {
  margin: 0;
}

.quote__text_type_italic,
.quote__text_weight_bold,
.quote__text_width_large {
  font-size: 28px;
}

.quote__text_type_italic {
  font-family: Roboto-Serif-Italic-Variable, sans-serif;
  font-weight: 150;
}

.quote__text_weight_bold {
  font-weight: 550;
}

.quote__text_width_large {
  font-weight: 150;
  font-stretch: 151%;
}

.quote__footer {
  margin: 0;
  text-align: end;
}

.quote__source {
  font-family: Roboto-Serif-Italic-Variable, sans-serif;
}

.hero__image {
  object-fit: cover;
  object-position: right;
  max-inline-size: 100%;
}

@media (min-width: 768px) {
  .hero__image {
    position: absolute;
    inset: auto 0 auto auto;
    z-index: -1;
    inline-size: 60%;
    min-inline-size: 300px;
  }
}

.theme-toggler {
  display: flex;
}

.theme-toggler__item {
  position: relative;
  box-sizing: border-box;
  border: 1px solid var(--accent-color);
  padding: 5px 20px;
  color: var(--accent-color);
  font-family: inherit;
  font-weight: 400;
  font-size: inherit;
  text-align: center;
  text-transform: uppercase;
  cursor: pointer;
  min-inline-size: 125px;
}

.theme-toggler__control {
  position: absolute;
  -webkit-appearance: none;
  appearance: none;
}

.theme-toggler__item:has(.theme-toggler__control:checked) {
  color: var(--main-color);
  font-weight: 800;
  background-color: var(--accent-color);
}
